#!/usr/bin/env python3
"""Every `//rtp_llm:<pkg>` reference must have a corresponding requirement() shim, and shim names must be unique.

Labels like `//rtp_llm:<pkg>` are py_library shims generated by `requirement([...])` in
`rtp_llm/BUILD`. Referencing a name not on the list makes the entire rtp_llm/BUILD fail
to load -- all targets in the package become unavailable at once. Listing the same name
twice duplicates the absent stub (`_absent_dep rule 'X__absent__arm' conflicts`), which
also breaks BUILD loading, so both directions are checked. Pure text parsing, no bazel or
toolchain needed, so it covers profiles that cannot be built locally.
Usage: python3 deps/check_rtp_llm_shims.py <open-source repo root>
"""
import re
import sys
from pathlib import Path

from pkgname import norm

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
# Only accept "target name" shapes: exclude visibility syntax like
# __subpackages__/__pkg__, and source-file references with extensions (e.g.
# //rtp_llm:release_version.py -- that is Label() reading a file, not a py_library shim).
LABEL_RE = re.compile(r'"//rtp_llm:([A-Za-z0-9][A-Za-z0-9._-]*)"')
_SKIP_RE = re.compile(r"^__\w+__$|\.(py|txt|json|so|sh|bzl|whl|tar|gz)$")


def _var_names(text, var, seen=None):
    """Expand string names in `var = ["a"] + other` (incl. nested variables, cycle-safe)."""
    seen = seen or set()
    if var in seen:
        return []
    seen.add(var)
    m = re.search(r"^%s\s*=\s*(\[[^\]]*\][^\n]*)" % re.escape(var), text, re.M)
    if not m:
        return []
    expr = m.group(1)
    out = re.findall(r'"([^"]+)"', expr)
    for nested in re.findall(r"\+\s*([A-Za-z_][A-Za-z_0-9]*)", expr):
        out += _var_names(text, nested, seen)
    return out


def _call_text(text, start):
    depth = 0
    for i in range(start, len(text)):
        if text[i] == "(":
            depth += 1
        elif text[i] == ")":
            depth -= 1
            if depth == 0:
                return text[start : i + 1]
    return text[start:]


def shim_names(build_text):
    """List of shim names generated by requirement() in rtp_llm/BUILD (**with duplicates**, duplicates are detected via it)."""
    names = []
    for m in re.finditer(r"requirement\s*\(", build_text):
        call = _call_text(build_text, m.end() - 1)
        names += re.findall(r'"([^"]+)"', call)
        for var in re.findall(r"\+\s*([A-Za-z_][A-Za-z_0-9]*)", call):
            names += _var_names(build_text, var)
    return names


def own_targets(build_text):
    """Target names explicitly declared in rtp_llm/BUILD (name = "x")."""
    return {
        m.group(1) for m in re.finditer(r'^\s*name\s*=\s*"([^"]+)"', build_text, re.M)
    }


def main():
    build = ROOT / "rtp_llm" / "BUILD"
    if not build.is_file():
        print("SKIP: rtp_llm/BUILD not found (pass the open-source repo root)")
        return 0
    text = build.read_text(encoding="utf-8", errors="replace")

    shims = shim_names(text)
    declared = {norm(n) for n in shims} | {norm(n) for n in own_targets(text)}

    problems = []

    # 1) Duplicates: the same name collected twice by requirement() -> absent stub conflict,
    #    whole BUILD fails to load
    seen, dup = set(), []
    for n in shims:
        k = norm(n)
        if k in seen and k not in dup:
            dup.append(k)
        seen.add(k)
    for k in dup:
        problems.append(
            "%s appears multiple times in the requirement() list -- the absent stub would be duplicated"
            " (_absent_dep rule '%s__absent__<profile>' conflicts), breaking the whole rtp_llm/BUILD load;"
            " list it only once in a single variable merged into requirement()"
            % (k, k.replace("-", "_"))
        )

    # 2) Dangling: referenced but has no shim/target
    refs = {}
    for path in list(ROOT.rglob("BUILD")) + list(ROOT.rglob("*.bzl")):
        sp = str(path)
        if "/3rdparty/" in sp or "/tmp/" in sp or "/bazel-" in sp:
            continue
        try:
            body = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for name in LABEL_RE.findall(body):
            if _SKIP_RE.search(name):
                continue
            if norm(name) not in declared:
                refs.setdefault(norm(name), set()).add(str(path.relative_to(ROOT)))
    for name in sorted(refs):
        problems.append(
            "%s is referenced by %s, but rtp_llm/BUILD has neither a target of that name nor lists it in requirement()"
            " -- a dangling reference breaks the whole rtp_llm/BUILD load (not just that target)"
            % (name, ", ".join(sorted(refs[name])))
        )

    if problems:
        for p in problems:
            print("FAIL " + p)
        sys.exit(1)
    print(
        "OK: %d requirement() shims without duplicates; all //rtp_llm:<pkg> references across the repo have a matching shim or target"
        % len(set(norm(n) for n in shims))
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
